Arguments: {"title":"Scrape rates for all May weekends on Arlo Hotels","code":"const tabId = 2136412301;

const weekends = [
  { name: "April 30 - May 2, 2027", arrive: "2027-04-30", depart: "2027-05-02" },
  { name: "May 7 - May 9, 2027", arrive: "2027-05-07", depart: "2027-05-09" },
  { name: "May 14 - May 16, 2027", arrive: "2027-05-14", depart: "2027-05-16" },
  { name: "May 21 - May 23, 2027", arrive: "2027-05-21", depart: "2027-05-23" },
  { name: "May 28 - May 30, 2027", arrive: "2027-05-28", depart: "2027-05-30" },
];

const results = [];

for (const w of weekends) {
  const url = `https://book.arlohotels.com/?adult=2&arrive=${w.arrive}&chain=19470&child=0&depart=${w.depart}&level=chain&locale=en-US&rooms=1`;
  console.log(`Checking ${w.name}...`);
  await tool.navigate({ tabId, url });

  // Wait for content to load
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 10000 });

  // Extract NYC hotel rates
  const hotelData = await browserjs(tabId, () => {
    const titles = Array.from(document.querySelectorAll('h2, h3, h4, .hotel-name, [class*="title"], [class*="name"]'))
      .filter(el => el.innerText?.includes('Arlo'));

    const res = {};
    titles.forEach(t => {
      let container = t.parentElement;
      for (let i = 0; i < 6; i++) {
        if (!container) break;
        if (container.innerText?.includes('Per Night') || container.innerText?.includes('VIEW RATES') || container.innerText?.includes('No rooms available')) {
          const match = container.innerText.match(/From\s*\$([0-9,]+)/i);
          const price = match ? parseInt(match[1].replace(/,/g, ''), 10) : null;
          res[t.innerText.trim()] = {
            pricePerNight: price,
